ok(firewall.includes('KFX047VisibleAudit'),'visible-language audit is exposed');
ok(stability.includes('scroll-behavior:auto!important'),'intake scrolling is deterministic');
ok(stability.includes('#openingBtn'),'opening control stability is explicitly owned');
ok(shell.includes('KFX047DReleaseAudit'),'startup shell exposes a release audit');
ok(shell.includes('body:not(.kfxStarted) #intro'),'startup shell guarantees visible intro before intake');
